### `CheckoutPage.tsx`

```tsx
import React, { useMemo, useState } from "react";
import type { CartItem, DeliveryAddress } from "./types";
import "./CheckoutPage.css";

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

const SHIPPING_FEE_CENTS = 499;

function formatPrice(cents: number): string {
  return (cents / 100).toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

function validate(address: DeliveryAddress): FormErrors {
  const errors: FormErrors = {};
  if (!address.fullName.trim()) errors.fullName = "Full name is required.";
  if (!address.street.trim()) errors.street = "Street address is required.";
  if (!address.city.trim()) errors.city = "City is required.";
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  }
  if (!address.country.trim()) errors.country = "Country is required.";
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }
  return errors;
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FormErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotalCents = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const shippingCents = items.length > 0 ? SHIPPING_FEE_CENTS : 0;
  const totalCents = subtotalCents + shippingCents;

  function handleFieldChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  async function handlePay(e: React.FormEvent) {
    e.preventDefault();
    const validationErrors = validate(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0) return;

    setPayError(null);
    setIsSubmitting(true);
    try {
      await onPay(address);
    } catch (err) {
      setPayError(
        err instanceof Error ? err.message : "Payment failed. Please try again."
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  const isCartEmpty = items.length === 0;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading">Order summary</h2>

          {isCartEmpty ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="price-breakdown">
            <div className="price-row">
              <dt>Subtotal</dt>
              <dd>{formatPrice(subtotalCents)}</dd>
            </div>
            <div className="price-row">
              <dt>Shipping</dt>
              <dd>{formatPrice(shippingCents)}</dd>
            </div>
            <div className="price-row price-row-total">
              <dt>Total</dt>
              <dd>{formatPrice(totalCents)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout-section delivery-form" aria-labelledby="delivery-heading">
          <h2 id="delivery-heading">Delivery address</h2>

          <form onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleFieldChange("fullName", e.target.value)}
                aria-invalid={Boolean(errors.fullName)}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
                autoComplete="name"
              />
              {errors.fullName && (
                <p className="field-error" id="fullName-error">
                  {errors.fullName}
                </p>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={(e) => handleFieldChange("street", e.target.value)}
                aria-invalid={Boolean(errors.street)}
                aria-describedby={errors.street ? "street-error" : undefined}
                autoComplete="street-address"
              />
              {errors.street && (
                <p className="field-error" id="street-error">
                  {errors.street}
                </p>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleFieldChange("city", e.target.value)}
                  aria-invalid={Boolean(errors.city)}
                  aria-describedby={errors.city ? "city-error" : undefined}
                  autoComplete="address-level2"
                />
                {errors.city && (
                  <p className="field-error" id="city-error">
                    {errors.city}
                  </p>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleFieldChange("postalCode", e.target.value)}
                  aria-invalid={Boolean(errors.postalCode)}
                  aria-describedby={errors.postalCode ? "postalCode-error" : undefined}
                  autoComplete="postal-code"
                />
                {errors.postalCode && (
                  <p className="field-error" id="postalCode-error">
                    {errors.postalCode}
                  </p>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={(e) => handleFieldChange("country", e.target.value)}
                aria-invalid={Boolean(errors.country)}
                aria-describedby={errors.country ? "country-error" : undefined}
                autoComplete="country-name"
              />
              {errors.country && (
                <p className="field-error" id="country-error">
                  {errors.country}
                </p>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={(e) => handleFieldChange("phone", e.target.value)}
                aria-invalid={Boolean(errors.phone)}
                aria-describedby={errors.phone ? "phone-error" : undefined}
                autoComplete="tel"
              />
              {errors.phone && (
                <p className="field-error" id="phone-error">
                  {errors.phone}
                </p>
              )}
            </div>

            {payError && (
              <p className="pay-error" role="alert">
                {payError}
              </p>
            )}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isCartEmpty || isSubmitting}
              >
                {isSubmitting ? "Processing…" : `Pay ${formatPrice(totalCents)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

